import threading

class LeaseManager:
    def __init__(self):
        self._lock = threading.Lock()
        self._leases = {}  # resource_id -> {fencing_token, expires_at_ms, worker_id}
        self._storage = {}  # resource_id -> {highest_issued_token, last_write_token}
        self._next_fencing_token = 1  # global counter for fencing tokens

    def acquire(self, resource_id: str, worker_id: str, ttl_ms: int, now_ms: int) -> dict:
        with self._lock:
            # Check if resource exists and is active
            if resource_id in self._leases:
                lease = self._leases[resource_id]
                if now_ms < lease['expires_at_ms']:
                    # Lease is active, cannot grant new lease
                    return {
                        "granted": False,
                        "fencing_token": None,
                        "expires_at_ms": lease['expires_at_ms']
                    }

            # No active lease or expired - create new lease
            new_token = self._next_fencing_token
            self._next_fencing_token += 1

            expires_at_ms = now_ms + ttl_ms
            self._leases[resource_id] = {
                "fencing_token": new_token,
                "expires_at_ms": expires_at_ms,
                "worker_id": worker_id
            }

            return {
                "granted": True,
                "fencing_token": new_token,
                "expires_at_ms": expires_at_ms
            }

    def renew(self, resource_id: str, worker_id: str, fencing_token: int, ttl_ms: int, now_ms: int) -> bool:
        with self._lock:
            if resource_id not in self._leases:
                return False

            lease = self._leases[resource_id]
            # Check if worker_id matches and fencing_token matches
            if lease['worker_id'] != worker_id or lease['fencing_token'] != fencing_token:
                return False

            # Check expiration and ttl
            if now_ms >= lease['expires_at_ms'] or ttl_ms <= 0:
                return False

            # Successfully renew - update expiration
            lease['expires_at_ms'] = now_ms + ttl_ms
            return True

    def release(self, resource_id: str, worker_id: str, fencing_token: int) -> bool:
        with self._lock:
            if resource_id not in self._leases:
                return False

            lease = self._leases[resource_id]
            # Check if worker_id matches and fencing_token matches
            if lease['worker_id'] != worker_id or lease['fencing_token'] != fencing_token:
                return False

            # Remove the lease
            del self._leases[resource_id]
            return True

    def write_resource(self, resource_id: str, fencing_token: int, value: str, now_ms: int) -> dict:
        # Validate inputs
        if not isinstance(resource_id, str) or not resource_id:
            return {"success": False, "reason": "INVALID_ARGUMENT"}
        if not isinstance(value, str):
            return {"success": False, "reason": "INVALID_ARGUMENT"}
        if not isinstance(now_ms, int) or isinstance(now_ms, bool):
            return {"success": False, "reason": "INVALID_ARGUMENT"}

        # Check if resource exists in storage
        if resource_id not in self._storage:
            return {"success": False, "reason": "STALE_TOKEN"}

        storage = self._storage[resource_id]
        highest_issued_token = storage['highest_issued_token']
        last_write_token = storage['last_write_token']

        # Token validation
        if fencing_token <= 0:
            return {"success": False, "reason": "STALE_TOKEN"}

        if fencing_token < max(highest_issued_token, last_write_token):
            return {"success": False, "reason": "STALE_TOKEN"}

        # Write is valid - update storage and lease
        self._storage[resource_id]['last_write_token'] = fencing_token
        self._leases[resource_id]['fencing_token'] = fencing_token
        self._leases[resource_id]['worker_id'] = worker_id

        return {"success": True, "reason": "OK"}

    def read_resource(self, resource_id: str) -> dict:
        with self._lock:
            if resource_id not in self._storage:
                return {"value": None, "last_token": 0}

            storage = self._storage[resource_id]
            return {
                "value": storage['last_write_token'],
                "last_token": storage['last_write_token']
            }
